create or replace function public.is_admin()
returns boolean language sql stable security definer set search_path=public
as $$ select exists(select 1 from public.profiles where profiles.id=auth.uid() and profiles.role='admin'); $$;
grant execute on function public.is_admin() to authenticated;

create or replace function public.set_updated_at()
returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end; $$;

create table if not exists public.employees(id bigint generated by default as identity primary key,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),name text not null,email text,phone text,job_title text,department text,status text not null default 'active',notes text);
create table if not exists public.opportunities(id bigint generated by default as identity primary key,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),client_id bigint references public.clients(id) on delete set null,title text not null,stage text not null default 'lead',estimated_value numeric(14,2) not null default 0,probability integer not null default 0 check(probability between 0 and 100),expected_close_date date,owner_id bigint references public.employees(id) on delete set null,source text,notes text);
create table if not exists public.tasks(id bigint generated by default as identity primary key,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),title text not null,description text,status text not null default 'todo',priority text not null default 'medium',due_date date,assigned_to bigint references public.employees(id) on delete set null,client_id bigint references public.clients(id) on delete set null,project_id bigint references public.projects(id) on delete set null);
create table if not exists public.campaigns(id bigint generated by default as identity primary key,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),client_id bigint references public.clients(id) on delete set null,name text not null,platform text,objective text,status text not null default 'planned',start_date date,end_date date,budget numeric(14,2) not null default 0,spent numeric(14,2) not null default 0,leads_count integer not null default 0,notes text);
create table if not exists public.quotations(id bigint generated by default as identity primary key,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),quote_number text unique,client_id bigint references public.clients(id) on delete set null,title text not null,status text not null default 'draft',subtotal numeric(14,2) not null default 0,tax_rate numeric(6,2) not null default 15,tax_amount numeric(14,2) not null default 0,total numeric(14,2) not null default 0,valid_until date,notes text);
create table if not exists public.quotation_items(id bigint generated by default as identity primary key,created_at timestamptz not null default now(),quotation_id bigint not null references public.quotations(id) on delete cascade,description text not null,quantity numeric(12,2) not null default 1,unit_price numeric(14,2) not null default 0,line_total numeric(14,2) generated always as(quantity*unit_price) stored);
create table if not exists public.contracts(id bigint generated by default as identity primary key,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),client_id bigint references public.clients(id) on delete set null,project_id bigint references public.projects(id) on delete set null,title text not null,status text not null default 'draft',start_date date,end_date date,value numeric(14,2) not null default 0,file_url text,notes text);
create table if not exists public.crm_activities(id bigint generated by default as identity primary key,created_at timestamptz not null default now(),client_id bigint references public.clients(id) on delete cascade,activity_type text not null default 'note',subject text,details text,activity_date timestamptz not null default now(),next_action_date date,created_by uuid references auth.users(id) on delete set null);
create table if not exists public.documents(id bigint generated by default as identity primary key,created_at timestamptz not null default now(),title text not null,document_type text,client_id bigint references public.clients(id) on delete set null,project_id bigint references public.projects(id) on delete set null,file_url text not null,notes text);
